using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

builder.Services.AddChatClient(chatClientBuilder => chatClientBuilder
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();
var noteService = host.Services.GetRequiredService<NoteService>();

var tools = new[]
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SearchWebNews),
    AIFunctionFactory.Create(noteService.AddNote),
    AIFunctionFactory.Create(noteService.GetNotes),
    AIFunctionFactory.Create(noteService.ClearNotes),
};

var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Instructions = """
        You are a research agent. Your job is to research a given topic thoroughly.

        Strategy:
        1. Search the web for relevant information on the topic.
        2. Take notes on key findings using the note-taking tool.
        3. Search for additional angles (news, different queries) to build comprehensive understanding.
        4. Once you have enough information, retrieve all notes and produce a final summary.

        Always take notes as you find useful information. Your final response should be a
        well-structured summary of your research findings with key points and sources.
        """,
    Tools = tools,
    DefaultOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
});

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (v1.0)       ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('─', 50));

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"\nResearch complete. {noteService.NoteCount} notes taken during research.");

// --- Tool implementations ---

/// <summary>Simulated web search tool for the research agent.</summary>
public sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new();

    [Description("Search the web for information on a query. Returns relevant search results.")]
    public Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        // In production, integrate with a real search API (Bing, Google, etc.)
        Console.WriteLine($"  🔍 Searching web: \"{query}\"");
        return Task.FromResult(
            $"[Search results for '{query}']\n" +
            $"1. Wikipedia article on {query} - comprehensive overview covering history, key concepts, and current state.\n" +
            $"2. Research paper: \"Advances in {query}\" (2025) - peer-reviewed study covering recent developments.\n" +
            $"3. Industry report on {query} - market analysis and future trends from leading analysts.\n" +
            $"4. Expert blog post: \"Understanding {query} in 2026\" - practical insights and real-world applications.");
    }

    [Description("Search the web for recent news articles on a query.")]
    public Task<string> SearchWebNews(
        [Description("The news search query")] string query)
    {
        Console.WriteLine($"  📰 Searching news: \"{query}\"");
        return Task.FromResult(
            $"[News results for '{query}']\n" +
            $"1. \"{query}: Major Breakthrough Announced\" - TechNews, July 2026\n" +
            $"2. \"Industry Leaders Discuss Future of {query}\" - Reuters, July 2026\n" +
            $"3. \"New Regulations Proposed for {query}\" - Policy Journal, June 2026");
    }
}

/// <summary>Note-taking service for accumulating research findings.</summary>
public sealed class NoteService
{
    private readonly List<string> _notes = [];

    public int NoteCount => _notes.Count;

    [Description("Add a research note to remember an important finding.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📋 Retrieving {_notes.Count} notes");
        return string.Join("\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }

    [Description("Clear all saved notes.")]
    public string ClearNotes()
    {
        _notes.Clear();
        return "All notes cleared.";
    }
}

