    AIFunctionFactory.Create(noteService.AddNote),
    AIFunctionFactory.Create(noteService.GetNotes),
    AIFunctionFactory.Create(noteService.ClearNotes),
};

var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
