     }
 }

 /// <summary>Note-taking service for accumulating research findings.</summary>
 public sealed class NoteService
 {
     private readonly List<string> _notes = [];

     public int NoteCount => _notes.Count;

     [Description("Add a research note to remember an important finding.")]
     public string AddNote(
         [Description("The note content to save")] string note)
     {
         _notes.Add(note);
         Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
         return $"Note saved. You now have {_notes.Count} note(s).";
     }

     [Description("Retrieve all saved research notes.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         Console.WriteLine($"  📋 Retrieving {_notes.Count} notes");
         return string.Join("\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
     }

     [Description("Clear all saved notes.")]
     public string ClearNotes()
     {
         _notes.Clear();
         return "All notes cleared.";
     }
 }

